import httpx

def run(body):
    r = httpx.Response(200, headers={"Content-Type": "multipart/x; boundary=b"}, content=body)
    try:
        ps = list(r.iter_multipart())
        return ("OK", [(p.headers.multi_items(), p.content) for p in ps])
    except Exception as e:
        return (type(e).__name__, str(e))

cases = {
    "open only": b"--b",
    "open CRLF": b"--b\r\n",
    "open then close": b"--b\r\n--b--\r\n",
    "open blank close": b"--b\r\n\r\n--b--\r\n",
    "headers no blank close": b"--b\r\nX: y\r\n--b--\r\n",
    "body to eof": b"--b\r\n\r\nfoo",
    "body to eof no final nl": b"--b\r\n\r\nfoo",
    "body crlf then close": b"--b\r\n\r\nfoo\r\n--b--",
    "body with blank before close": b"--b\r\n\r\nfoo\r\n\r\n--b--\r\n",
}
for name, body in cases.items():
    print(name, "->", run(body))
